// The bell: unread count (polled, and refreshed after every change) and the
// inbox panel. Reminders are generated by the server; this only shows them.
import { useCallback, useEffect, useRef, useState } from 'react';
import { api } from '../lib/api';
import { useFinance } from '../lib/finance';
import { timeAgo } from '../lib/format';
import { navigate } from '../lib/router';
import type { AppNotification, NotificationKind } from '../lib/types';
import { Icon, type IconName } from './Icon';
import { Empty, Link, Modal, Skeleton } from './ui';

export const kindMeta: Record<NotificationKind, { icon: IconName; label: string; tone: string }> = {
  budget_warning: { icon: 'pie', label: 'Anggaran hampir habis', tone: 'warn' },
  budget_over: { icon: 'pie', label: 'Anggaran terlewati', tone: 'danger' },
  bill_due: { icon: 'repeat', label: 'Tagihan rutin besok', tone: 'neutral' },
  bill_failed: { icon: 'alert', label: 'Tagihan gagal karena saldo kurang', tone: 'danger' },
  low_balance: { icon: 'wallet', label: 'Saldo dompet menipis', tone: 'warn' },
  goal_achieved: { icon: 'target', label: 'Target tabungan tercapai', tone: 'ok' },
  daily_reminder: { icon: 'clock', label: 'Pengingat malam bila belum mencatat', tone: 'neutral' },
  weekly_summary: { icon: 'chart', label: 'Ringkasan mingguan (Senin)', tone: 'neutral' },
};

export function NotificationBell({ className }: { className?: string }) {
  const { version } = useFinance();
  const [unread, setUnread] = useState(0);
  const [open, setOpen] = useState(false);

  const refresh = useCallback(() => {
    api.get<{ unread: number }>('/notifications/unread').then((r) => setUnread(r.unread)).catch(() => {});
  }, []);

  // Poll once a minute, and shortly after any change (the server builds
  // event-driven notices in a background worker, a moment after the write).
  useEffect(() => {
    refresh();
    const t = setInterval(refresh, 60_000);
    return () => clearInterval(t);
  }, [refresh]);
  useEffect(() => {
    if (version === 0) return;
    const t = setTimeout(refresh, 700);
    return () => clearTimeout(t);
  }, [version, refresh]);

  return (
    <>
      <button type="button" className={'icon-btn bell ' + (className ?? '')} onClick={() => setOpen(true)}
        aria-label={unread ? `Notifikasi, ${unread} belum dibaca` : 'Notifikasi'} aria-haspopup="dialog">
        <Icon name="bell" />
        {unread > 0 && <span className="bell-count" aria-hidden="true">{unread > 9 ? '9+' : unread}</span>}
      </button>
      <Modal open={open} onClose={() => { setOpen(false); refresh(); }} title="Notifikasi">
        {open && <Inbox onClose={() => { setOpen(false); refresh(); }} onRead={refresh} />}
      </Modal>
    </>
  );
}

function Inbox({ onClose, onRead }: { onClose: () => void; onRead: () => void }) {
  const [items, setItems] = useState<AppNotification[] | null>(null);
  const loaded = useRef(false);

  useEffect(() => {
    if (loaded.current) return;
    loaded.current = true;
    api.get<{ items: AppNotification[] }>('/notifications').then((r) => setItems(r.items)).catch(() => setItems([]));
  }, []);

  async function open(n: AppNotification) {
    if (!n.readAt) await api.post('/notifications/read', { ids: [n.id] }).catch(() => {});
    onRead();
    onClose();
    if (n.link) navigate(n.link);
  }

  async function readAll() {
    await api.post('/notifications/read', { all: true }).catch(() => {});
    setItems((list) => list?.map((n) => ({ ...n, readAt: n.readAt ?? new Date().toISOString() })) ?? null);
    onRead();
  }

  if (!items) return <div style={{ display: 'grid', gap: 12 }}>{[0, 1, 2].map((i) => <Skeleton key={i} h={52} />)}</div>;
  const unread = items.filter((n) => !n.readAt).length;

  return (
    <div className="inbox">
      <div className="inbox-head">
        <span className="muted">{unread ? `${unread} belum dibaca` : 'Semua sudah dibaca'}</span>
        <div style={{ display: 'flex', gap: 6 }}>
          {unread > 0 && <button className="btn btn-quiet btn-sm" onClick={readAll}>Tandai semua dibaca</button>}
          <Link to="/app/notifikasi" className="btn btn-ghost btn-sm" onClick={onClose}><Icon name="edit" size={14} /> Atur</Link>
        </div>
      </div>
      {items.length === 0 ? (
        <Empty icon="bell" title="Belum ada notifikasi">Receh akan memberi tahu saat anggaran hampir habis, tagihan jatuh tempo, atau saldo menipis.</Empty>
      ) : (
        <ul className="inbox-list">
          {items.map((n) => {
            const meta = kindMeta[n.kind] ?? { icon: 'bell' as IconName, tone: 'neutral' };
            return (
              <li key={n.id}>
                <button type="button" className={'inbox-item' + (n.readAt ? '' : ' unread')} onClick={() => open(n)}>
                  <span className={'inbox-icon tone-' + meta.tone}><Icon name={meta.icon} size={18} /></span>
                  <span className="inbox-text">
                    <strong>{n.title}</strong>
                    <span>{n.body}</span>
                    <small>{timeAgo(n.createdAt)}</small>
                  </span>
                  {!n.readAt && <span className="unread-dot" aria-label="Belum dibaca" />}
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}
